"""Test PR tab notification matching logic.

Validates that _notify_tab / _show_bell / _clear_tab_bell
work correctly with dynamic tab text like "PR:5".
"""


class FakeNotebook:
    """Minimal notebook stub for testing tab notification matching."""

    def __init__(self, tabs: dict[str, str]):
        """tabs: {tab_id: tab_text}"""
        self._tabs = dict(tabs)
        self._selected = list(tabs.keys())[0]
        self._images: dict[str, str] = {}

    def tabs(self) -> list[str]:
        return list(self._tabs.keys())

    def tab(self, tab_id: str, option: str = "", **kwargs) -> str | None:
        if kwargs:
            if "text" in kwargs:
                self._tabs[tab_id] = kwargs["text"]
            if "image" in kwargs:
                self._images[tab_id] = kwargs["image"]
            return None
        if option == "text":
            return self._tabs.get(tab_id, "")
        return ""

    def select(self) -> str:
        return self._selected


class FakeBellManager:
    """Mimics dashboard's bell logic extracted for testing."""

    def __init__(self, notebook: FakeNotebook):
        self._notebook = notebook
        self._notified_tabs: set[str] = set()
        self._persistent_tabs: set[str] = set()
        self._notify_bg = "bell_image"

    def notify_tab(self, tab_name: str) -> None:
        selected_id = self._notebook.select()
        selected_text = self._notebook.tab(selected_id, "text")
        if selected_text.startswith(tab_name):
            return
        if tab_name in self._notified_tabs:
            return
        self._notified_tabs.add(tab_name)
        self._show_bell(tab_name)

    def _show_bell(self, tab_name: str) -> None:
        for tab_id in self._notebook.tabs():
            if self._notebook.tab(tab_id, "text").startswith(tab_name):
                self._notebook.tab(tab_id, image=self._notify_bg)
                break

    def _hide_bell(self, tab_name: str) -> None:
        for tab_id in self._notebook.tabs():
            if self._notebook.tab(tab_id, "text").startswith(tab_name):
                self._notebook.tab(tab_id, image="")
                break

    def clear_tab_bell(self, tab_name: str) -> None:
        self._notified_tabs.discard(tab_name)
        if tab_name not in self._persistent_tabs:
            self._hide_bell(tab_name)

    def has_bell(self, tab_id: str) -> bool:
        return self._notebook._images.get(tab_id) == "bell_image"


class TestTabNotificationMatching:
    """Verify bell set/clear works with dynamic tab names."""

    def _make_notebook(self, selected: str = "chat") -> FakeNotebook:
        nb = FakeNotebook(
            {
                "chat": "Chat",
                "pr": "PR:5",
                "console": "Console",
            }
        )
        nb._selected = selected
        return nb

    def test_notify_pr_tab_from_other_tab(self):
        """Bell appears on PR tab when viewing another tab."""
        nb = self._make_notebook(selected="chat")
        mgr = FakeBellManager(nb)
        mgr.notify_tab("PR")
        assert mgr.has_bell("pr")
        assert "PR" in mgr._notified_tabs

    def test_notify_pr_tab_while_viewing_pr_tab(self):
        """Bell should NOT appear when already viewing PR tab."""
        nb = self._make_notebook(selected="pr")
        mgr = FakeBellManager(nb)
        mgr.notify_tab("PR")
        assert not mgr.has_bell("pr")
        assert "PR" not in mgr._notified_tabs

    def test_clear_bell_with_base_name(self):
        """Clear with base name "PR" correctly clears bell stored as "PR".

        _on_tab_changed now extracts base name for PR tabs,
        so it calls clear_tab_bell("PR") matching the stored key.
        """
        nb = self._make_notebook(selected="chat")
        mgr = FakeBellManager(nb)
        mgr.notify_tab("PR")
        assert mgr.has_bell("pr")

        # Simulate fixed _on_tab_changed: extracts "PR" from "PR:5"
        mgr.clear_tab_bell("PR")
        assert "PR" not in mgr._notified_tabs
        assert not mgr.has_bell("pr")

    def test_clear_bell_with_correct_name(self):
        """Clear with "PR" correctly removes bell."""
        nb = self._make_notebook(selected="chat")
        mgr = FakeBellManager(nb)
        mgr.notify_tab("PR")
        assert mgr.has_bell("pr")

        mgr.clear_tab_bell("PR")
        assert "PR" not in mgr._notified_tabs
        assert not mgr.has_bell("pr")

    def test_show_bell_startswith_matching(self):
        """_show_bell matches "PR" against "PR:5" via startswith."""
        nb = self._make_notebook(selected="chat")
        mgr = FakeBellManager(nb)
        mgr._show_bell("PR")
        assert mgr.has_bell("pr")

    def test_show_bell_exact_name_no_match(self):
        """_show_bell with "PRs" does NOT match "PR:5"."""
        nb = self._make_notebook(selected="chat")
        mgr = FakeBellManager(nb)
        mgr._show_bell("PRs")
        assert not mgr.has_bell("pr")

    def test_repeated_notifications_after_clear(self):
        """Bell can fire again after being cleared by tab switch."""
        nb = self._make_notebook(selected="chat")
        mgr = FakeBellManager(nb)

        # First notification
        mgr.notify_tab("PR")
        assert mgr.has_bell("pr")

        # User clicks PR tab — clears bell
        mgr.clear_tab_bell("PR")
        assert not mgr.has_bell("pr")
        assert "PR" not in mgr._notified_tabs

        # User switches back to Chat
        nb._selected = "chat"

        # Second notification — must work
        mgr.notify_tab("PR")
        assert mgr.has_bell("pr")

    def test_console_exact_match(self):
        """Console tab has static name — exact match works."""
        nb = self._make_notebook(selected="chat")
        mgr = FakeBellManager(nb)
        mgr.notify_tab("Console")
        assert mgr.has_bell("console")
        mgr.clear_tab_bell("Console")
        assert not mgr.has_bell("console")
        assert "Console" not in mgr._notified_tabs
